// Step 1 of the search: ask Gemini to turn the question into exact rules.
// Gemini does NOT pick candidates here; code checks the rules in the next step.
const event = $('Slack question').first().json;
const question = (event.text || '').replace(/<@[^>]+>/g, '').trim();
if (!question) throw new Error('Empty question');

const roles = $('Get roles').all().map(i => i.json).filter(r => r.id);
const roleList = roles.length
  ? roles.map(r => `[role ${r.id}] ${r.title} for ${r.client_name}. Must-haves: ${(r.must_haves || []).join('; ')}. Nice-to-haves: ${(r.nice_to_haves || []).join('; ')}`).join('\n')
  : '(no open roles)';

const instructions = `You turn a recruiter's question into search rules for a CV database. Do not answer the question.

Skill names (use exactly these when they apply): gohighlevel, zapier, n8n, make, api_webhooks, hubspot,
clickfunnels, activecampaign, meta_ads, google_ads, ga4, klaviyo, tiktok_ads, seo,
phone_support, chat_support, zendesk, freshdesk, intercom, healthcare, medical_admin, hipaa,
athenahealth, eclinicalworks, epic, insurance_verification, prior_auth,
quickbooks_online, xero, sage, bank_reconciliations, us_clients, uk_clients.

Rules:
- requirements: every hard requirement that is a skill. Each requirement is a list of acceptable options (any_of).
  "3+ years of GHL" -> [{skill: gohighlevel, min_years: 3}].
  "Zapier or n8n" -> ONE requirement with two options.
  "1+ year of phone or chat support" -> ONE requirement: phone_support 1 or chat_support 1.
  A skill with no number -> min_years 0.
- languages: languages the candidate must speak, lowercase English names (e.g. "arabic").
- other_requirements: hard requirements that are not a listed skill or a language
  (e.g. "managed $20k+/month in ad spend", "QuickBooks ProAdvisor certification").
- nice_to_haves: things that are a plus but not required.
- If the question names or clearly refers to one of the open roles, set role_id to it and include that
  role's must-haves as requirements/languages/other_requirements, and its nice-to-haves as nice_to_haves.
  Otherwise role_id is 0 and you use only what the question says.

Open roles:
${roleList}`;

const option = {
  type: 'object',
  properties: { skill: { type: 'string' }, min_years: { type: 'number' } },
  required: ['skill', 'min_years'], additionalProperties: false
};
const schema = {
  type: 'object',
  properties: {
    role_id: { type: 'integer' },
    requirements: {
      type: 'array',
      items: { type: 'object', properties: { any_of: { type: 'array', items: option } }, required: ['any_of'], additionalProperties: false }
    },
    languages: { type: 'array', items: { type: 'string' } },
    other_requirements: { type: 'array', items: { type: 'string' } },
    nice_to_haves: { type: 'array', items: { type: 'string' } }
  },
  required: ['role_id', 'requirements', 'languages', 'other_requirements', 'nice_to_haves'],
  additionalProperties: false
};

return [{
  json: {
    question: question,
    channel: event.channel,
    body: {
      model: 'gemini-3.5-flash-lite',
      system_instruction: instructions,
      input: [{ type: 'text', text: 'Question: ' + question }],
      response_format: { type: 'text', mime_type: 'application/json', schema: schema }
    }
  }
}];

// Step 2 of the search: check EVERY candidate against the rules, in plain code.
// Code never overlooks anyone, so the shortlist can't miss a qualified person.
const req = $('Build filter request').first().json;
const reply = $input.first().json;

function geminiJson(r) {
  if (r.error) throw new Error(typeof r.error === 'string' ? r.error : (r.error.description || r.error.message || 'API error'));
  if (r.status && r.status !== 'completed') throw new Error('Gemini did not finish: ' + r.status);
  const steps = r.steps || [];
  const output = steps.filter(s => s.type === 'model_output').pop() || steps[steps.length - 1];
  const textPart = ((output && output.content) || []).find(c => c.type === 'text');
  return JSON.parse(textPart ? textPart.text : r.output_text);
}

let rules = null;
let problem = '';
try { rules = geminiJson(reply); } catch (e) { problem = e.message; }

// "gohighlevel 3.7y, make 3.7y" -> { gohighlevel: 3.7, make: 3.7 }
const parseSkills = text => Object.fromEntries((text || '').split(',').map(s => s.trim()).filter(Boolean).map(s => {
  const m = s.match(/^(.*)\s([\d.]+)y$/);
  return m ? [m[1].trim().toLowerCase(), parseFloat(m[2])] : [s.toLowerCase(), 0];
}));

const describe = r => r.any_of.map(o => o.min_years > 0 ? `${o.skill} ${o.min_years}+ yrs` : o.skill).join(' or ');

const candidates = $('Get candidates').all().map(i => i.json).filter(c => c.id);
const matched = [];
const nearMisses = [];

if (rules) {
  const requirements = (rules.requirements || []).filter(r => (r.any_of || []).length);
  const languages = (rules.languages || []).map(l => l.toLowerCase().trim()).filter(Boolean);

  for (const c of candidates) {
    const skills = parseSkills(c.skills);
    const langs = (c.languages || []).map(l => String(l).toLowerCase());
    const missing = [];

    for (const r of requirements) {
      const ok = r.any_of.some(o => (skills[String(o.skill).toLowerCase()] ?? -1) >= (o.min_years || 0));
      if (!ok) {
        const has = r.any_of.map(o => skills[String(o.skill).toLowerCase()]).filter(v => v !== undefined);
        missing.push(describe(r) + (has.length ? ` (has ${Math.max(...has)} yrs)` : ''));
      }
    }
    for (const l of languages) if (!langs.includes(l)) missing.push('speaks ' + l);

    // How much experience beyond the minimum, used to keep the best when there are many.
    const extra = requirements.reduce((sum, r) => sum + Math.max(0, ...r.any_of.map(o => (skills[String(o.skill).toLowerCase()] ?? 0) - (o.min_years || 0))), 0);

    if (!missing.length) matched.push({ ...c, extra });
    else if (missing.length === 1) nearMisses.push({ name: c.full_name, cv_file: c.cv_file_name, missing: missing[0] });
  }
  matched.sort((a, b) => b.extra - a.extra);
}

return [{
  json: {
    question: req.question,
    channel: req.channel,
    problem: problem,
    rules: rules,
    rules_text: rules ? [...(rules.requirements || []).map(describe), ...(rules.languages || []).map(l => 'speaks ' + l), ...(rules.other_requirements || [])].join(', ') : '',
    matched: matched.slice(0, 25),
    matched_count: matched.length,
    near_misses: nearMisses.slice(0, 3)
  }
}];

// Step 3 of the search: Gemini scores and explains ONLY the candidates code already approved.
const f = $input.first().json;

const candidateList = f.matched.map(c =>
  `[id ${c.id}] ${c.full_name} | ${c.headline} | ${c.location}\n` +
  `languages: ${(c.languages || []).join(', ')}\n` +
  `skills (years): ${c.skills}\n` +
  `CV text: ${(c.cv_text || c.summary || '').replace(/\s+/g, ' ').slice(0, 1500)}`
).join('\n\n');

const instructions = `You rank candidates for a recruiter. Every candidate below ALREADY meets these requirements
(checked by code): ${f.rules_text || '(none)'}.

Your job:
1. Remove a candidate only if their CV clearly fails one of these other requirements: ${(f.rules.other_requirements || []).join('; ') || '(none)'}.
   If the CV does not mention it, keep them and name it as the risk in line 2.
2. Score each remaining candidate from 0 to 100: 60 for meeting the requirements,
   up to 25 for experience beyond the minimum, up to 15 for these nice-to-haves: ${(f.rules.nice_to_haves || []).join('; ') || '(none)'}.
3. Return at most 5, best first. Use only ids from the list. Never invent a candidate or a number.
4. reason: exactly two short lines separated by "\\n". Line 1: why they fit, with the real numbers from the list.
   Line 2: the main gap or risk, or a bonus. Under 25 words each.
5. If every candidate fails the other requirements, return no matches and explain why in no_match_reason.`;

const schema = {
  type: 'object',
  properties: {
    matches: {
      type: 'array',
      items: {
        type: 'object',
        properties: { candidate_id: { type: 'integer' }, score: { type: 'integer' }, reason: { type: 'string' } },
        required: ['candidate_id', 'score', 'reason'], additionalProperties: false
      }
    },
    no_match_reason: { type: 'string' }
  },
  required: ['matches', 'no_match_reason'],
  additionalProperties: false
};

return [{
  json: {
    body: {
      model: 'gemini-3.5-flash-lite',
      system_instruction: instructions,
      input: [{ type: 'text', text: `Recruiter question: ${f.question}\n\nCandidates (${f.matched.length}):\n\n${candidateList}` }],
      response_format: { type: 'text', mime_type: 'application/json', schema: schema }
    }
  }
}];

// Final step: build the Slack answer. Only candidates that passed the code check can appear,
// and names and CV files come from the database, never from the AI.
const f = $('Apply filters').first().json;
const roles = $('Get roles').all().map(i => i.json).filter(r => r.id);
const role = roles.find(r => f.rules && Number(r.id) === Number(f.rules.role_id));
const allowed = new Map(f.matched.map(c => [Number(c.id), c]));

let matches = [];
let aiNote = '';
let noMatchReason = '';

if (f.matched.length) {
  let answer = null;
  try {
    const r = $input.first().json;
    if (r.error) throw new Error(typeof r.error === 'string' ? r.error : (r.error.description || r.error.message || 'API error'));
    const steps = r.steps || [];
    const output = steps.filter(s => s.type === 'model_output').pop() || steps[steps.length - 1];
    const textPart = ((output && output.content) || []).find(c => c.type === 'text');
    answer = JSON.parse(textPart ? textPart.text : r.output_text);
  } catch (e) {
    aiNote = e.message;
  }

  if (answer) {
    const seen = new Set();
    matches = (answer.matches || [])
      .filter(m => allowed.has(Number(m.candidate_id)) && !seen.has(Number(m.candidate_id)) && seen.add(Number(m.candidate_id)))
      .map(m => ({ c: allowed.get(Number(m.candidate_id)), score: Math.max(0, Math.min(100, Math.round(m.score))), reason: String(m.reason || '').trim() }));
    noMatchReason = answer.no_match_reason || '';
  } else {
    // AI unavailable: still answer, ranked by experience beyond the minimum.
    matches = f.matched.slice(0, 5).map(c => ({
      c, score: Math.min(85, 60 + Math.round(c.extra * 5)),
      reason: `Meets: ${f.rules_text}.\nSkills: ${c.skills.split(', ').slice(0, 4).join(', ')}`
    }));
  }
}

matches = matches.sort((a, b) => b.score - a.score).slice(0, 5).map(m => ({
  candidate_id: Number(m.c.id), name: m.c.full_name, cv_file: m.c.cv_file_name, score: m.score, reason: m.reason
}));

let text;
if (f.problem) {
  text = `:warning: I couldn't understand "${f.question}" right now (${f.problem}). Please ask again in a minute.`;
} else if (!matches.length) {
  const close = f.near_misses.map(n => `• ${n.name}: missing ${n.missing} (:page_facing_up: ${n.cv_file})`).join('\n');
  text = `:mag: *No good match* for "${f.question}".\n` +
    `Nobody meets all of: ${f.rules_text || 'the requirements'}.` +
    (noMatchReason ? `\n${noMatchReason}` : '') +
    (close ? `\n\n*Closest:*\n${close}` : '') +
    `\n\nI won't suggest someone who doesn't fit.`;
} else {
  const lines = matches.map((m, i) =>
    `*${i + 1}. ${m.name}*: ${m.score}/100\n${m.reason.split('\n').map(l => '> ' + l).join('\n')}\n> :page_facing_up: ${m.cv_file}`);
  text = `:mag: *Top ${matches.length}* for "${f.question}"` + (role ? ` (role #${role.id}: ${role.title})` : '') +
    `\n_Checked all candidates for: ${f.rules_text}_` + (aiNote ? `\n_(AI ranking unavailable, ranked by experience)_` : '') +
    `\n\n` + lines.join('\n\n');
}

return [{
  json: {
    question: f.question,
    channel: f.channel,
    role_id: role ? Number(role.id) : 0,
    role_title: role ? role.title : '',
    matches: matches,
    candidate_ids: matches.map(m => m.candidate_id).join(','),
    shortlist_rows: role ? matches.map(m => ({ role_id: Number(role.id), candidate_id: m.candidate_id, score: m.score, reason: m.reason, source_cv: m.cv_file })) : [],
    text: text
  }
}];

